/**
 * Every case plants a real value generated by `node:crypto`, not a lookalike.
 * The false-alarm cases matter as much as the catching ones: a check that
 * blocks commits carrying no key gets skipped.
 */

import { generateKeyPairSync } from "node:crypto";
import { describe, expect, it } from "vitest";
import { findSecretIn, SECRET_PATTERNS, SELF_EXEMPT_PATHS } from "./secret-patterns.mjs";

function keyPair(privateFormat) {
  return generateKeyPairSync("rsa", {
    modulusLength: 2048,
    publicKeyEncoding: { type: "spki", format: "pem" },
    privateKeyEncoding: { type: "pkcs8", format: privateFormat },
  });
}

describe("the PEM rule catches a real private key", () => {
  it("catches a PKCS#8 key as written to disk, header and body on separate lines", () => {
    expect(findSecretIn(keyPair("pem").privateKey)).toBe("PEM private key");
  });

  /**
   * The escaped form `.dev.vars` holds the GitHub App key in. A line-based
   * scan could catch only one of the escaped and plain forms.
   */
  it("catches a key escaped into a dotenv line", () => {
    const escaped = `ONCUE_GITHUB_APP_PRIVATE_KEY="${keyPair("pem").privateKey.replaceAll("\n", "\\n")}"`;

    expect(findSecretIn(escaped)).toBe("PEM private key");
  });

  it("catches a key embedded in a source file among other code", () => {
    const source = `const config = {\n  key: \`${keyPair("pem").privateKey}\`,\n};\n`;

    expect(findSecretIn(source)).toBe("PEM private key");
  });

  it("catches PKCS#1 and SEC1 headers too, not only PKCS#8", () => {
    const pkcs8 = keyPair("pem").privateKey;
    const pkcs1 = pkcs8.replaceAll("PRIVATE KEY", "RSA PRIVATE KEY");
    const sec1 = pkcs8.replaceAll("PRIVATE KEY", "EC PRIVATE KEY");

    expect(findSecretIn(pkcs1)).toBe("PEM private key");
    expect(findSecretIn(sec1)).toBe("PEM private key");
  });
});

describe("the PEM rule does not cry wolf", () => {
  /** The hosted config carries Clerk's public key, which reaches the Worker bundle. */
  it("ignores a real public key", () => {
    expect(findSecretIn(keyPair("pem").publicKey)).toBeNull();
  });

  /** `worker/github/app.ts` has to name these to slice a key out of a PEM. */
  it("ignores the marker constants a PEM parser must declare", () => {
    const source =
      'const PEM_BEGIN = "-----BEGIN PRIVATE KEY-----";\nconst PEM_END = "-----END PRIVATE KEY-----";\n';

    expect(findSecretIn(source)).toBeNull();
  });

  it("ignores prose that mentions a key format", () => {
    const comment = " * GitHub downloads an App key as PKCS#1 (BEGIN RSA PRIVATE KEY), which\n";

    expect(findSecretIn(comment)).toBeNull();
  });

  /**
   * The interpolation marker is assembled rather than written, because
   * `noTemplateCurlyInString` flags a literal `${` in a quoted string.
   */
  it("ignores a fixture that interpolates a generated key at runtime", () => {
    const interpolationStart = `$${"{"}`;
    const source = `return \`-----BEGIN PRIVATE KEY-----\\n${interpolationStart}lines.join("\\n")}\\n-----END PRIVATE KEY-----\\n\`;\n`;

    expect(findSecretIn(source)).toBeNull();
  });

  it("ignores a body far too short to be a key", () => {
    const source = '"-----BEGIN RSA PRIVATE KEY-----\\nAAAA\\n-----END RSA PRIVATE KEY-----\\n"\n';

    expect(findSecretIn(source)).toBeNull();
  });
});

describe("the provider token rules", () => {
  const catches = [
    ["Clerk secret key", "sk_test_abcdefgh12345678"],
    ["Clerk secret key", "sk_live_abcdefgh12345678"],
    ["Anthropic API key", "sk-ant-api03-AAAAAAAAAAAAAAAA"],
    ["OpenAI project key", "sk-proj-AAAAAAAAAAAAAAAA"],
    ["OpenAI project key", "sk-svcacct-AAAAAAAAAAAAAAAA"],
    ["OpenAI legacy key", `sk-${"A".repeat(48)}`],
    ["GitHub token", "ghs_A1b2C3d4E5f6G7h8I9j0"],
    ["GitHub token", "ghu_A1b2C3d4E5f6G7h8I9j0"],
    ["GitHub token", "gho_A1b2C3d4E5f6G7h8I9j0"],
    ["GitHub token", "ghp_A1b2C3d4E5f6G7h8I9j0"],
  ];

  for (const [name, value] of catches) {
    it(`catches a ${name}`, () => {
      expect(findSecretIn(`const key = "${value}";`)).toBe(name);
    });
  }

  /** A loose `sk-` would fire on ordinary identifiers. */
  const ignores = [
    "a bare sk- in a test name",
    "the identifier CLERK_SECRET_KEY on its own",
    "a short prefix like ghs_ with nothing after it",
    "a hashed bundle identifier such as sk-Ab12",
  ];

  for (const text of ignores) {
    it(`ignores ${text}`, () => {
      expect(findSecretIn(text)).toBeNull();
    });
  }
});

describe("the module's own contract", () => {
  it("names every pattern, so a refusal can say what it found without printing it", () => {
    for (const { name, pattern } of SECRET_PATTERNS) {
      expect(typeof name).toBe("string");
      expect(name.length).toBeGreaterThan(0);
      expect(pattern).toBeInstanceOf(RegExp);
    }
  });

  /** A scanner matches its own source, so only files that name the shapes may be exempt. */
  it("exempts only the files whose job is to name these shapes", () => {
    expect([...SELF_EXEMPT_PATHS].sort()).toEqual([
      ".husky/pre-commit",
      "apps/web/scripts/check-no-secret-in-bundle.mjs",
      "apps/web/scripts/check-staged-secrets.mjs",
      "apps/web/scripts/secret-patterns.mjs",
      "apps/web/scripts/secret-patterns.test.mjs",
    ]);
  });
});
